    type MemberDetails,
  } from "./lib/entity-details";
  let { details }: { details: MemberDetails } = $props();
</script>

<div class="member-summary-top">
  <section class="member-overview" aria-labelledby="overview-heading">
    <h2 id="overview-heading">Known declared value</h2>
    <p class="summary-context">
      Across {details.declarations.length} stored declarations. Includes earnings,
      gifts and support.
    </p>
    {#if details.summary.firstRegisteredAt && details.summary.lastRegisteredAt}<p
        class="stored-coverage"
      >
        Registered {registrationDate(details.summary.firstRegisteredAt)} to {registrationDate(
          details.summary.lastRegisteredAt,
        )}.{#if details.summary.undatedDeclarationCount}
          {details.summary.undatedDeclarationCount} declarations have no registration
          date.{/if}
      </p>{/if}
    {#if details.summary.currencies.length === 0}<p class="empty-details">
        {details.summary.entryCount === 0
          ? "No funding entries are stored for this MP."
          : "No known currencies are available for totals."}
      </p>{/if}
    <div class="member-currency-totals">
      {#each details.summary.currencies as group}<div>
          <h3>{group.currency}</h3>
          <p class="member-total">{formatAmount(group.amount)}</p>
          <p class="entry-count">
            {group.entryCount} funding {group.entryCount === 1
              ? "entry"
              : "entries"}{#if group.unknownAmountCount}, {group.unknownAmountCount}
              amounts unavailable{/if}
          </p>
        </div>{/each}
    </div>
    {#if details.summary.undatedDeclarationCount && !details.summary.firstRegisteredAt}<p
        class="stored-coverage"
      >
        Registration dates are unavailable.
      </p>{/if}
    {#if details.summary.unknownCurrencyCount}<p class="coverage-note">
        {details.summary.unknownCurrencyCount} funding {details.summary
          .unknownCurrencyCount === 1
          ? "entry has"
          : "entries have"} an unknown currency and are excluded from monetary totals.
      </p>{/if}
  </section>
  <section class="member-breakdown" aria-labelledby="breakdown-heading">
    <h2 id="breakdown-heading">Declared value by category</h2>
    <p class="summary-context">
      Amounts recorded in each category, with currencies kept separate.
    </p>
    {#each details.summary.currencies as group}
      {@const bars = categoryBars(group.categories)}
      {@const signed = bars.some((bar) => bar.negative)}
      <div class="category-currency">
        <h3>{group.currency}</h3>
        <ul class="category-list">
          {#each group.categories as category, index}<li>
              <div class="category-label">
                <span>{category.categoryName}</span><span class="amount"
                  >{formatAmount(category.amount)} {group.currency}</span
                >
              </div>
              <div class="signed-bar" class:signed aria-hidden="true">
                <span
                  class:negative={bars[index].negative}
                  style:width={`${bars[index].width / (signed ? 2 : 1)}%`}
                ></span>
              </div>
              {#if category.unknownAmountCount}<p class="partial-note">
                  {category.unknownAmountCount} amounts unavailable
                </p>{/if}
            </li>{/each}
        </ul>
      </div>
    {/each}
  </section>
</div>
<section aria-labelledby="recent-declarations-heading">
  <div class="detail-section-heading">
    <h2 id="recent-declarations-heading">Recent declarations</h2>
    <p>The latest five stored declarations across all categories.</p>
  </div>
  {#if details.declarations.length}<MemberDeclarations
      declarations={details.declarations.slice(0, 5)}
    />{:else}<p class="empty-details">
      No declarations are stored for this MP.
    </p>{/if}
  <a
    class="text-button history-link"
    href={memberHref(details.member.id, "history")}
    >View all {details.declarations.length} declarations</a
  >
</section>
<script lang="ts">
  import Icon from "./lib/Icon.svelte";
  import { memberHref, type MemberProfile } from "./lib/entity-details";
  let { member, view }: { member: MemberProfile; view: "summary" | "history" } =
    $props();
</script>

<header class="member-identity">
  <div class="member-identity-title">
    <span class="profile-type"><Icon name="parliament" size={20} />MP</span>
    <h1>{member.name}</h1>
  </div>
  <p>
    {member.partyName || "Party unavailable"}<span
      >{member.membershipFrom || "Membership unavailable"}</span
    ><span>{member.isCurrentCommons ? "Current MP" : "Former MP"}</span>
  </p>
  <nav class="member-tabs" aria-label="Member views">
    <a
      href={memberHref(member.id, "summary")}
      aria-current={view === "summary" ? "page" : undefined}>Summary</a
    >
    <a
      href={memberHref(member.id, "history")}
      aria-current={view === "history" ? "page" : undefined}
      >Declaration history</a
    >
  </nav>
</header>
<script lang="ts">
  import { entityHref } from "./lib/search";
  import {
    formatAmount,
    registrationDate,
    type MemberDeclaration,
  } from "./lib/entity-details";
  let { declarations }: { declarations: MemberDeclaration[] } = $props();
</script>

<ol class="declarations-list member-declarations">
  {#each declarations as declaration}
    <li class="declaration">
      <header class="declaration-heading">
        <div>
          <h3>{declaration.categoryName}</h3>
          <span class="declaration-reference"
            >Declaration {declaration.sourceId}</span
          >
        </div>
        <p>
          {#if declaration.registeredAt}<time
              datetime={declaration.registeredAt}
              >{registrationDate(declaration.registeredAt)}</time
            >{:else}Registration date unavailable{/if}
        </p>
      </header>
      {#if declaration.entries.length === 0}<p class="empty-entry">
          No funding entries recorded.
        </p>
      {:else}
        <ul class="funding-list">
          {#each declaration.entries as entry}
            <li>
              <div class="funding-source">
                {#if entry.funder}<a
                    href={entityHref({
                      kind: "Funder",
                      id: entry.funder.id,
                    })}>{entry.funder.name}</a
                  >{:else}<span>Funder unavailable</span>{/if}<span
                  class="payment-type"
                  >{entry.paymentType || "Payment type unavailable"}</span
                >
              </div>
              <div class="funding-value">
                <span class="amount">{formatAmount(entry.amount)}</span><span
                  class="currency-label"
                  >{entry.currency?.trim() || "Currency unavailable"}</span
                >
              </div>
            </li>
          {/each}
        </ul>
      {/if}
    </li>
  {/each}
</ol>
<script lang="ts">
  import MemberIdentity from "./MemberIdentity.svelte";
  import MemberSummary from "./MemberSummary.svelte";
  import MemberHistory from "./MemberHistory.svelte";
  import Icon from "./lib/Icon.svelte";
  import { entityHref, funderKindLabel } from "./lib/search";
  import {
    backToSearch,
    formatAmount,
    loadDetails,
    type DetailRoute,
    type DetailState,
  } from "./lib/entity-details";
  let { route }: { route: Exclude<DetailRoute, { kind: "search" }> } = $props();
  let attempt = $state(0);
  let detailState = $state<DetailState>({ kind: "loading" });
  const backHref = backToSearch();
  $effect(() => {
    const currentRoute = route;
    void attempt;
    if (currentRoute.kind === "invalid") {
      detailState = { kind: "not-found" };
      return;
    }
    const controller = new AbortController();
    let current = true;
    detailState = { kind: "loading" };
    void loadDetails(currentRoute, controller.signal)
      .then((result) => {
        if (current) detailState = result;
      })
      .catch(() => {});
    return () => {
      current = false;
      controller.abort();
    };
  });
</script>

<main
  id="details"
  class="detail-page"
  class:member-page={route.kind === "member"}
  class:funder-page={route.kind === "funder"}
  aria-busy={detailState.kind === "loading"}
>
  <a class="back-link" href={backHref}>Back to search</a>
  {#if detailState.kind === "loading"}
    <div class="detail-message" role="status">
      <span class="loading-indicator" aria-hidden="true"></span>
      <h1>Loading details</h1>
    </div>
  {:else if detailState.kind === "not-found"}
    <div class="detail-message">
      <h1>Entity not found</h1>
      <p>
        This MP or funder is not in the stored register. Search for another
        name.
      </p>
      <a class="text-button" href={backHref}>Search MPs and funders</a>
    </div>
  {:else if detailState.kind === "error"}
    <div class="detail-message" role="alert">
      <h1>Details couldn’t load</h1>
      <p>{detailState.message}</p>
      <button class="retry-button" onclick={() => (attempt += 1)}
        ><Icon name="retry" size={16} />Try again</button
      >
    </div>
  {:else if detailState.kind === "member"}
    {@const details = detailState.details}
    <MemberIdentity
      member={details.member}
      view={route.kind === "member" ? route.view : "summary"}
    />
    {#if route.kind === "member" && route.view === "history"}<MemberHistory
        {details}
      />{:else}<MemberSummary {details} />{/if}
  {:else}
    {@const details = detailState.details}
    <header class="profile-heading">
      <span class="profile-type"><Icon name="coin" size={22} />Funder</span>
      <h1>{details.funder.name}</h1>
      <p class="profile-meta">{funderKindLabel(details.funder.funderKind)}</p>
      <dl class="profile-facts">
        {#if details.funder.companyNumber}<div>
            <dt>Company number</dt>
            <dd>{details.funder.companyNumber}</dd>
          </div>{/if}
        <div>
          <dt>Recorded support</dt>
          <dd>
            {details.entryCount}
            {details.entryCount === 1 ? "funding entry" : "funding entries"}
          </dd>
        </div>
      </dl>
    </header>
    {#if details.funder.aliases.length > 0}
      <section class="recorded-names" aria-labelledby="recorded-names-heading">
        <h2 id="recorded-names-heading">Recorded names</h2>
        <ul>
          {#each details.funder.aliases as alias}
            <li>{alias}</li>
          {/each}
        </ul>
      </section>
    {/if}
    <p class="summary-context">
      Declared support is grouped by recipients’ latest stored party. It may
      include payments or benefits beyond direct donations. Parties do not
      describe membership when support was received.
    </p>
    {#if details.unknownCurrencyCount > 0}<p class="coverage-note">
        {details.unknownCurrencyCount}
        {details.unknownCurrencyCount === 1 ? "entry has" : "entries have"} an unknown
        currency and {details.unknownCurrencyCount === 1 ? "is" : "are"} excluded
        from totals and rankings.
      </p>{/if}
    {#if details.currencies.length === 0}<p class="empty-details">
        {details.entryCount === 0
          ? "No funding entries are stored for this funder."
          : "No known currencies are available for totals or rankings."}
      </p>
    {:else}
      {#each details.currencies as group}
        <section
