      calls === 1
        ? { status: 503, body: "private database error" }
        : { json: memberDetails },
    );
  });
  await page.goto("/members/1?q=Example&strictness=0.4");
  await expect(page.getByRole("alert")).toContainText("Details couldn’t load");
