<script lang="ts">
  import { categoryBars, registrationDate } from "./lib/entity-details";
  import { formatPounds, type EarningsWeek } from "./lib/member-summary";
  let { weeks, undated }: { weeks: EarningsWeek[]; undated: boolean } = $props();
  const bars = $derived(categoryBars(weeks));
  const positive = $derived(Math.max(0, ...bars.filter(bar => !bar.negative).map(bar => bar.width)));
  const negative = $derived(Math.max(0, ...bars.filter(bar => bar.negative).map(bar => bar.width)));
  const extent = $derived(positive + negative || 100);
  const baseline = $derived(24 + positive / extent * 184);
  const maximum = $derived(weeks[bars.findIndex(bar => !bar.negative && bar.width === positive)]?.amount ?? "0");
  const minimum = $derived(weeks[bars.findIndex(bar => bar.negative && bar.width === negative)]?.amount ?? "0");
  function tick(index: number): boolean {
    return index === 0 || index === weeks.length - 1 || (weeks.length > 10 && index % Math.ceil(weeks.length / 4) === 0);
  }
  function month(start: string): string {
    return new Intl.DateTimeFormat("en-GB", { month: "short", year: "numeric", timeZone: "UTC" }).format(new Date(start));
  }
</script>

