  <p class="chart-subtitle">By registration week</p>
  {#if weeks.length}
    <svg class="earnings-chart" viewBox="0 0 560 250" role="img" aria-labelledby="earnings-title earnings-description">
      <title id="earnings-title">Weekly registered earnings</title>
      <desc id="earnings-description">Pound amounts by Monday registration week. Exact amounts are available in the weekly earnings table below.</desc>
      <text x="0" y="16" class="chart-axis">{formatPounds(maximum)}</text>
      <line x1="0" x2="560" y1={baseline} y2={baseline} class="chart-baseline" />
      {#each weeks as week, index}
        {@const bar = bars[index]}
        {@const height = bar.width / extent * 184}
        <rect x={index * 560 / weeks.length + 1} y={bar.negative ? baseline : baseline - height} width={Math.max(1, 560 / weeks.length - 2)} height={height} class="earnings-bar" class:negative={bar.negative}><title>Week of {registrationDate(week.start)}: {formatPounds(week.amount)}{week.incomplete ? " (some amounts unavailable)" : ""}</title></rect>
        {#if tick(index)}<text x={index * 540 / Math.max(1, weeks.length - 1) + 10} y="244" text-anchor={index === 0 ? "start" : index === weeks.length - 1 ? "end" : "middle"} class="chart-axis">{month(week.start)}</text>{/if}
      {/each}
      <text x="0" y={negative ? 225 : Math.min(225, baseline + 16)} class="chart-axis">{negative ? formatPounds(minimum) : "£0"}</text>
    </svg>
    {#if weeks.some(week => week.incomplete)}<p class="partial-note">Some weekly amounts are unavailable.</p>{/if}
    <details class="earnings-values"><summary>View weekly amounts</summary><table><caption class="visually-hidden">Weekly registered earnings</caption><thead><tr><th scope="col">Week starting</th><th scope="col">Declared earnings</th></tr></thead><tbody>{#each weeks as week}<tr><th scope="row"><time datetime={week.start}>{registrationDate(week.start)}</time></th><td>{formatPounds(week.amount)}{#if week.incomplete}<span class="partial-note">Some amounts unavailable</span>{/if}</td></tr>{/each}</tbody></table></details>
  {:else}<p class="empty-details">{undated ? "Registration dates are unavailable for earnings." : "No registered earnings available."}</p>{/if}
  {#if undated && weeks.length}<p class="partial-note">Earnings without registration dates are excluded.</p>{/if}
</section>
EOF
