import { summarizeMember, formatPounds } from "../src/lib/member-summary";
import type { MemberDetails, MemberDeclaration, FundingEntry } from "../src/lib/entity-details";

function entry(amount: string | null, currency: string | null = "GBP"): FundingEntry {
  return { amount, currency, funder: null, paymentType: null };
}
function declaration(registeredAt: string | null, entries: FundingEntry[], categoryName = "Employment and earnings", categoryId = 12): MemberDeclaration {
  return { registeredAt, entries, categoryName, categoryId, sourceId: 1 };
}
function details(declarations: MemberDeclaration[]): MemberDetails {
  return {
    member: { id: "1", name: "Example", partyName: "", membershipFrom: "", isCurrentCommons: true }, declarations,
