  };
}

test("summary preserves duplicate arbitrary precision values and server pounds total", () => {
  const summary = summarizeMember(details([declaration("2026-01-05T00:00:00Z", [entry("9007199254740993.123456789"), entry("9007199254740993.123456789"), entry("0.000000001")])]));
