  expect(summary.earnings).toEqual([{ start: "2026-01-05", amount: "18014398509481986.246913579", incomplete: false }]);
  expect(formatPounds(summary.earnings[0].amount)).toBe("£18,014,398,509,481,986.246913579");
  expect(formatPounds("-5")).toBe("−£5.00");
  expect(formatPounds(null)).toBe("Amount unavailable");
});

test("UTC registration weeks preserve negatives, zero, gaps and incomplete values", () => {
  const summary = summarizeMember(details([
    declaration("2025-12-28T23:00:00-02:00", [entry("-2.5")]),
